# Normalize spelling and abbreviations before applying domain rules. All output
# values are deliberately unaccented so the result is stable across environments.
SPELLINGS = {
    "indijena": "indigena",
    "indijino": "indigena",
    "indigino": "indigena",
    "indigina": "indigena",
    "indijina": "indigena",
    "indo": "indio",
    "espanola": "espanol",
    "espanoles": "espanol",
    "indios": "indio",
    "hijos": "hijo",
    "hijas": "hija",
    "naturales": "natural",
    "legitimos": "legitimo",
    "legitimas": "legitima",
}

ABBREVIATIONS = {
    "hn": "hijo natural",
    "hl": "hijo legitimo",
    "id": "indigena",
}

# These are the canonical value inventories for the requested facets.
ETHNO_RACIAL = {
    "indio": "indigena",
    "india": "indigena",
    "indigena": "indigena",
    "mestiza": "mestizo",
    "espanol": "espanol",
    "vecino": "vecino",
    "tributario": "tributario",
}

LEGITIMACY = {
    "natural": "natural",
    "legitimo": "legitimo",
    "legitima": "legitimo",
    "espurio": "espurio",
    "hijo natural": "natural",
    "hija natural": "natural",
    "hijo legitimo": "legitimo",
    "hija legitima": "legitimo",
    "hijo espurio": "espurio",
    "hija espuria": "espurio",
}

LOCATIONS = {"aucara", "ishua", "pampamarca", "chacralla", "punas"}


def clean(text):
    """Lowercase, remove accents/punctuation, and collapse whitespace."""
    text = unicodedata.normalize("NFKD", text.lower())
    text = "".join(c for c in text if not unicodedata.combining(c))
    text = re.sub(r"[^a-z0-9 ]+", " ", text)
    return " ".join(text.split())


def normalize_token(token):
    token = clean(token)
    # Expand an abbreviation only when it is a complete token. This avoids
    # replacing letter sequences inside ordinary words.
    if token in ABBREVIATIONS:
        return ABBREVIATIONS[token]
    return " ".join(SPELLINGS.get(word, word) for word in token.split())


def classify(term):
    """Extract any matching facets from a normalized one- or multiword term."""
    words = term.split()
    result = {
        "Ethno-Racial Category": set(),
        "Legitimacy Status": set(),
        "Geographic Location": set(),
    }

    # Exact multiword legal labels take precedence over their component words.
    if term in LEGITIMACY:
        result["Legitimacy Status"].add(LEGITIMACY[term])

    for word in words:
        if word in ETHNO_RACIAL:
            result["Ethno-Racial Category"].add(ETHNO_RACIAL[word])
        if word in LEGITIMACY:
            result["Legitimacy Status"].add(LEGITIMACY[word])
        if word in LOCATIONS:
            result["Geographic Location"].add(word)

    # Abbreviations expand to phrases; classify the expanded legal expression.
    if term == "hijo natural":
        result["Legitimacy Status"].add("natural")
    elif term == "hijo legitimo":
        result["Legitimacy Status"].add("legitimo")

    return {key: sorted(values) for key, values in result.items()}


def parse_clusters(raw):
    clusters = {}
    for line in raw.splitlines():
        match = re.match(r"Cluster\s+(\d+):\s*(.*)", line.strip())
        if not match:
            continue
        cluster_id, body = match.groups()
        terms = [part.strip() for part in body.split(",") if part.strip()]

        normalized_terms = sorted({normalize_token(term) for term in terms})
        cluster_result = {
            "terms": {},
            "facets": {
                "Ethno-Racial Category": set(),
                "Legitimacy Status": set(),
                "Geographic Location": set(),
            },
        }

        for term in normalized_terms:
            facets = classify(term)
            cluster_result["terms"][term] = facets
            for facet, values in facets.items():
                cluster_result["facets"][facet].update(values)

        cluster_result["facets"] = {
            facet: sorted(values)
            for facet, values in cluster_result["facets"].items()
        }
        clusters[cluster_id] = cluster_result

    return clusters


if __name__ == "__main__":
    print(json.dumps(parse_clusters(RAW), ensure_ascii=False, indent=2))
